text_ar:
حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ حَدَّثَنَا غُنْدَرٌ حَدَّثَنَا شُعْبَةُ عَنْ أَبِي إِسْحَاقَ قَالَ سَمِعْتُ عَبْدَ الرَّحْمَنِ بْنَ يَزِيدَ عَنْ عَبْدِ اللَّهِ
قَالَ بَنِي إِسْرَائِيلَ وَالْكَهْفُ وَمَرْيَمُ وَطه وَالْأَنْبِيَاءُ هُنَّ مِنْ الْعِتَاقِ الْأُوَلِ وَهُنَّ مِنْ تِلَادِي
وَقَالَ قَتَادَةُ
{ جُذَاذًا }
قَطَّعَهُنَّ وَقَالَ الْحَسَنُ
{ فِي فَلَكٍ }
مِثْلِ فَلْكَةِ الْمِغْزَلِ
{ يَسْبَحُونَ }
يَدُورُونَ قَالَ ابْنُ عَبَّاسٍ
{ نَفَشَتْ }
رَعَتْ لَيْلًا
{ يُصْحَبُونَ }
يُمْنَعُونَ
{ أُمَّتُكُمْ أُمَّةً وَاحِدَةً }
قَالَ دِينُكُمْ دِينٌ وَاحِدٌ وَقَالَ عِكْرِمَةُ
{ حَصَبُ }
حَطَبُ بِالْحَبَشِيَّةِ وَقَالَ غَيْرُهُ
{ أَحَسُّوا }
تَوَقَّعُوا مِنْ أَحْسَسْتُ
{ خَامِدِينَ }
هَامِدِينَ وَالْحَصِيدُ مُسْتَأْصَلٌ يَقَعُ عَلَى الْوَاحِدِ وَالِاثْنَيْنِ وَالْجَمِيعِ
{ لَا يَسْتَحْسِرُونَ }
لَا يُعْيُونَ وَمِنْهُ
{ حَسِيرٌ }
وَحَسَرْتُ بَعِيرِي عَمِيقٌ بَعِيدٌ نُكِّسُوا رُدُّوا
{ صَنْعَةَ لَبُوسٍ }
الدُّرُوعُ
{ تَقَطَّعُوا أَمْرَهُمْ }
اخْتَلَفُوا الْحَسِيسُ وَالْحِسُّ وَالْجَرْسُ وَالْهَمْسُ وَاحِدٌ وَهُوَ مِنْ الصَّوْتِ الْخَفِيِّ
{ آذَنَّاكَ }
أَعْلَمْنَاكَ
{ آذَنْتُكُمْ }
إِذَا أَعْلَمْتَهُ فَأَنْتَ وَهُوَ
{ عَلَى سَوَاءٍ }
لَمْ تَغْدِرْ وَقَالَ مُجَاهِدٌ
{ لَعَلَّكُمْ تُسْأَلُونَ }
تُفْهَمُونَ
{ ارْتَضَى }
رَضِيَ
{ التَّمَاثِيلُ }
الْأَصْنَامُ السِّجِلُّ الصَّحِيفَةُ

text_ar_search:
حدثنا محمد بن بشار حدثنا غندر حدثنا شعبة عن أبي إسحاق قال سمعت عبد الرحمن بن يزيد عن عبد الله
قال بني إسرائيل والكهف ومريم وطه والأنبياء هن من العتاق الأول وهن من تلادي
وقال قتادة
{ جذاذا }
قطعهن وقال الحسن
{ في فلك }
مثل فلكة المغزل
{ يسبحون }
يدورون قال ابن عباس
{ نفشت }
رعت ليلا
{ يصحبون }
يمنعون
{ أمتكم أمة واحدة }
قال دينكم دين واحد وقال عكرمة
{ حصب }
حطب بالحبشية وقال غيره
{ أحسوا }
توقعوا من أحسست
{ خامدين }
هامدين والحصيد مستأصل يقع على الواحد والاثنين والجميع
{ لا يستحسرون }
لا يعيون ومنه
{ حسير }
وحسرت بعيري عميق بعيد نكسوا ردوا
{ صنعة لبوس }
الدروع
{ تقطعوا أمرهم }
اختلفوا الحسيس والحس والجرس والهمس واحد وهو من الصوت الخفي
{ آذناك }
أعلمناك
{ آذنتكم }
إذا أعلمته فأنت وهو
{ على سواء }
لم تغدر وقال مجاهد
{ لعلكم تسألون }
تفهمون
{ ارتضى }
رضي
{ التماثيل }
الأصنام السجل الصحيفة
